      <p v-if="section==='about'" class="kimi-signature">Kimi Cain <small>{{settings.credential}}</small></p>
     </div></div>
    </section>
    <section v-if="['home','about','services','counseling','consultation'].includes(section)" class="kimi-values"><div class="kimi-wrap"><article v-for="v in settings.values" :key="v.title"><Icon :name="v.icon"/><h2>{{v.title}}</h2><p v-if="section==='services'">{{v.body}}</p></article></div></section>

    <section v-if="['home','services'].includes(section)" class="kimi-section kimi-wrap"><div class="kimi-heading"><p class="kimi-eyebrow">Support that meets you where you are</p><h2>Find Your Way Forward</h2></div><div class="kimi-three"><article v-for="s in settings.services" :key="s.title" class="kimi-card"><span class="kimi-icon"><Icon :name="s.icon"/></span><h3>{{s.title}}</h3><span class="kimi-rule"/><p>{{s.body}}</p><router-link class="kimi-text-link" :to="path(s.path)">{{s.label}} →</router-link></article></div></section>

    <section v-if="['home','about','services'].includes(section)" class="kimi-section kimi-story-section"><div class="kimi-wrap kimi-two"><img v-if="section!=='about'" class="kimi-square" :src="safe(settings.squareUrl)" alt="Kimi Cain" loading="lazy"/><div v-else class="kimi-landscape" :style="mountainStyle"><p>You are more capable<br/>than you know.</p></div><div><p class="kimi-eyebrow">{{settings.story?.eyebrow}}</p><h2>{{section==='services'?'Meet Kimi':settings.story?.title}}</h2><p v-for="paragraph in settings.story?.paragraphs" :key="paragraph">{{paragraph}}</p><p class="kimi-editorial">You don’t have to figure it out alone.</p><router-link class="kimi-button" :to="path(section==='about'?'consultation':'about')">{{section==='about'?'Work With Me':'Get to Know Kimi'}} →</router-link></div></div></section>
    <section v-if="section==='about'" class="kimi-section kimi-wrap kimi-three"><article><Icon name="leaf"/><h3>Credentials & Training</h3><ul><li>{{settings.credential}}</li><li>Master’s-level provider, with supervised counseling through NLU</li><li>Learning services through NLU</li><li>Ongoing professional development</li></ul></article><article><Icon name="people"/><h3>My Approach</h3><p>{{settings.approach}}</p></article><article><Icon name="heart"/><h3>What Drives Me</h3><p>{{settings.motivation}}</p></article></section>

