<script setup>
import {computed,ref,onMounted,watch} from 'vue';
import Icon from '../../components/rise/RiseIcon.vue';
import KimiConsultationForm from '../../components/public/KimiConsultationForm.vue';
import {useStandalonePublicWebsite,publicWebsiteUrl} from '../../composables/useStandalonePublicWebsite';
import api from '../../services/api';
const {route,page,loading,error,menuOpen,section:rawSection,settings,path,load,preview,previewNotice,guardPreview}=useStandalonePublicWebsite('kimi','Kimi Cain | Life Coaching');
const section=computed(()=>({'':'home','coaching-packages':'packages','book':'consultation','join':'enroll','services-support':'services'}[rawSection.value]||rawSection.value));
const hero=computed(()=>settings.value.pages?.[section.value]);
const nav=[['Home',''],['About','about'],['Services','services'],['Coaching Packages','packages'],['Counseling','counseling'],['Resources','resources'],['Contact','contact']];
const nluJoin='/join/nlu/counseling?source=kimi';
const safe=publicWebsiteUrl;
const mountainStyle=computed(()=>({'--kimi-mountain':`url(${JSON.stringify(safe(settings.value.mountainUrl))})`}));
const packages=ref([]),catalogLoading=ref(true),catalogError=ref(false);
async function loadCatalog(){catalogLoading.value=true;catalogError.value=false;try{const{data}=await api.get('/public/marketing-pages/kimi/coaching-catalog',{skipAuthRedirect:true,skipGlobalLoading:true});packages.value=data.packages||[];}catch{catalogError.value=true;}finally{catalogLoading.value=false;}}
onMounted(loadCatalog);
const selectedPackage=computed(()=>packages.value.find(p=>String(p.id)===String(route.query.package)));
const enrollmentUrl=computed(()=>'/intake/kimi-coaching-enrollment'+(selectedPackage.value?'?coachingPackage='+encodeURIComponent(selectedPackage.value.key):''));
const money=c=>c==null?'Contact Kimi for pricing':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100);
let descriptionElement=null;
watch([hero,page],()=>{if(!hero.value)return;document.title=`${hero.value.title.replace(/\n/g,' ')} | Kimi Cain Life Coaching`;descriptionElement=document.querySelector('meta[name="description"]');if(descriptionElement)descriptionElement.content=hero.value.body;},{immediate:true});
</script>
